"""Diagnostic only: does independent candidate-to-anchor text evidence explain missed matches?"""
from pathlib import Path
import sys,json
import numpy as np,polars as pl
from rapidfuzz import process,fuzz
R=Path(__file__).resolve().parents[2];O=Path(__file__).parent;KEY=['s1','src','eid'];s=pl.read_parquet(R/'experiments/astra_011/relative_evidence_dev_scored.parquet');ids=s.select('s1').unique().sort('s1').head(2000);s=s.join(ids,on='s1',how='semi');x=pl.read_parquet(R/'experiments/astra_011/dev/parts/*.parquet').join(ids,on='s1',how='semi');pool=pl.concat([pl.scan_parquet(R/f'work/cache/train_source{i}.parquet').join(s.filter(pl.col('src')==i).select('eid').unique().lazy(),on='eid',how='semi').select('src','eid','name','addr').collect() for i in [2,3]]);cand=s.join(pool,on=['src','eid']);anchors=cand.filter(pl.col('score')>=.99).sort('score',descending=True).group_by('s1',maintain_order=True).head(3).select('s1',pl.col('src').alias('anchor_src'),pl.col('eid').alias('anchor_eid'),pl.col('name').alias('anchor_name'),pl.col('addr').alias('anchor_addr'));j=cand.join(anchors,on='s1').filter((pl.col('src')!=pl.col('anchor_src'))|(pl.col('eid')!=pl.col('anchor_eid')))
if j.height:
 ns=process.cpdist(j['name'].to_list(),j['anchor_name'].to_list(),scorer=fuzz.token_sort_ratio,workers=2)/100;ads=process.cpdist(j['addr'].to_list(),j['anchor_addr'].to_list(),scorer=fuzz.token_sort_ratio,workers=2)/100;j=j.with_columns(pl.Series('anchor_joint',ns*ads));e=j.group_by(KEY).agg(pl.col('anchor_joint').max());out=x.join(s.select(*KEY,'score'),on=KEY).join(e,on=KEY,how='left').with_columns((pl.col('anchor_joint')-pl.col('name_x_addr')).alias('improvement'));out=out.with_columns(pl.when((pl.col('label')==1)&(pl.col('score')<.75)).then(pl.lit('false_negative')).when((pl.col('label')==0)&(pl.col('score')>=.75)).then(pl.lit('false_positive')).when(pl.col('label')==1).then(pl.lit('true_positive')).otherwise(pl.lit('true_negative')).alias('category'));summary=out.group_by('category').agg(pl.len(),pl.col('anchor_joint').is_not_null().sum().alias('with_anchor'),pl.col('improvement').median().alias('median_anchor_gain'),((pl.col('improvement')>.15)&(pl.col('anchor_joint')>.65)).sum().alias('strong_additional_evidence'));summary.write_csv(O/'diagnostic.csv');out.filter(pl.col('category').is_in(['false_negative','false_positive'])).write_parquet(O/'errors.parquet');print(summary)
